function chair(s) {
  return `<svg viewBox="0 0 240 190" role="img" aria-label="Hot seat at ${round(s.heat)} percent"><defs><linearGradient id="flame" x2="0" y2="1"><stop stop-color="#ffc76b"/><stop offset="1" stop-color="#fb562e"/></linearGradient></defs><ellipse cx="120" cy="170" rx="80" ry="12" fill="#ea6420" opacity=".12"/>${s.heat > 15 ? `<g class="flames" opacity="${0.3 + s.heat / 150}"><path d="M58 155 Q20 110 61 61 Q53 105 84 93 Q80 49 116 ${Math.max(0, 68 - s.heat)} Q107 65 140 86 Q159 67 164 43 Q205 110 175 155Z" fill="url(#flame)"/><path d="M87 156 Q65 127 91 99 Q88 124 113 113 Q114 79 130 66 Q126 117 150 119 Q170 144 151 159Z" fill="#ffcf70"/></g>` : ""}<g stroke="#131b1c" stroke-width="5" stroke-linejoin="round"><path d="M87 139 L79 177 M155 139 L164 177" stroke="#a5a7a0" stroke-width="9"/><rect x="75" y="60" width="91" height="71" rx="14" fill="#52615b"/><path d="M87 72h65v46H87z" fill="#65756c" stroke-width="2"/><rect x="69" y="125" width="105" height="23" rx="8" fill="#8a9a87"/><path d="M65 105v28m113-28v28" stroke="#a5a7a0" stroke-width="8"/><path d="M53 103h27m85 0h26" stroke="#b7bbae" stroke-width="9"/></g></svg>`;
}
